import sys

def find_palindrome_parts(s):
    n = len(s)
    def is_palindrome(l, r):
        while l < r:
            if s[l] != s[r]:
                return False
            l += 1
            r -= 1
        return True

    max_length = 0
    result = []

    for i in range(n):
        for j in range(i, n):
            if (j - i + 1) % 2 == 1 and is_palindrome(i, j):
                length = j - i + 1
                if length > max_length:
                    max_length = length
                    result = [(i + 1, length)]
                elif length == max_length:
                    result.append((i + 1, length))

    if not result:
        return [(1, 1)]

    return result

s = sys.stdin.read().strip()
parts = find_palindrome_parts(s)
print(len(parts))
for xi, li in parts:
    print(xi, li)
